gdr.ValidationScript:
var FieldsNames = {
	SubmittedDocType: "SubmittedDocType__",
	SplitOption: "Split_DivisionMethod__",
	SplitOffset: "Split_Offset__",
	SplitNumberOfPage: "Split_NumberPages__",
	SplitString: "Split_String__",
	SplitArea: "Split_Area__",
	SplitUseRegex: "Split_UseRegex__",
	SplitCaseSensitive: "Split_CaseSensitive__",
	SplitSearchOnFirstPage: "Split_Location__",
	PDFCommand: "MOD_Option_PDFCommand__",
	SkipMethod: "Skip_Method__",
	SkipArea: "Skip_Area__",
	SkipCriteria: "Skip_Criteria__",
	SkipIsRegex: "Skip_CriteriaIsRegex__",
	SkipMatchCase: "Skip_CriteriaMatchCase__"
};

var FieldErrors = {
	Required: "This field is required",
	PositiveValue: "This field must be positive",
	Malformatted: "This field is malformatted (X, Y, Height, Width)"
};

var StepIndexes = {
	General: 0
};

var regExpAreaValidation = /(?:\s*-?\d+\s*),(?:\s*-?\d+\s*),(?:\s*\d+\s*),(?:\s*\d+\s*)/;

var SplittingHandler = {
	splittingMehods: { "SIMPLE": "noDivision", "NPAGES": "fixedPageNumber", "ONSTRING": "stringSplit", "ONAREA": "areaSplit" },

	FormSplittingIsComplete: function ()
	{
		var comboValue = Data.GetValue(FieldsNames.SplitOption);

		var offsetValue = Data.GetValue(FieldsNames.SplitOffset);
		if (offsetValue === "" || Data.GetError(FieldsNames.SplitOffset) !== "")
		{
			Data.SetError(FieldsNames.SplitOffset, FieldErrors.Required);
			return false;
		}

		if (offsetValue < 0)
		{
			Data.SetError(FieldsNames.SplitOffset, FieldErrors.PositiveValue);
			return false;
		}

		if (comboValue === "NPAGES")
		{
			var value = Data.GetValue(FieldsNames.SplitNumberOfPage);
			if (value === "" || Data.GetError(FieldsNames.SplitNumberOfPage) !== "")
			{
				Data.SetError(FieldsNames.SplitNumberOfPage, FieldErrors.Required);
				return false;
			}
			else if (value < 0)
			{
				Data.SetError(FieldsNames.SplitNumberOfPage, FieldErrors.PositiveValue);
				return false;
			}
			return true;
		}
		else if (comboValue === "ONSTRING" && (Data.GetValue(FieldsNames.SplitString) === ""))
		{
			Data.SetError(FieldsNames.SplitString, FieldErrors.Required);
			return false;
		}
		else if (comboValue === "ONAREA")
		{
			var valid = regExpAreaValidation.test(Data.GetValue(FieldsNames.SplitArea));
			if (!valid)
			{
				Data.SetError(FieldsNames.SplitArea, FieldErrors.Malformatted);
			}
			return valid;
		}

		return true;
	},

	Process: function ()
	{
		var splitResult = null;
		var stringPreviewDocSplitting = "";

		if (this.FormSplittingIsComplete())
		{
			var nbPages = (Data.GetValue(FieldsNames.SubmittedDocType) || "pdf") === "pdf" ? Attach.GetProcessedConvertedFile().GetNbPages() : 1;
			Variable.SetValueAsString("nbTotalPages", nbPages);

			var skipMethod = Data.GetValue(FieldsNames.SkipMethod);
			var splitOffset = Data.GetValue(FieldsNames.SplitOffset);
			var skipArea = Data.GetValue(FieldsNames.SkipArea);
			var skipCriteria = Data.GetValue(FieldsNames.SkipCriteria);
			var skipIsRegex = Data.GetValue(FieldsNames.SkipIsRegex);
			var skipMatchCase = Data.GetValue(FieldsNames.SkipMatchCase);

			var offsetValue = Lib.DD.Splitting.GetOffset(skipMethod, splitOffset, nbPages, skipArea, skipMatchCase, skipIsRegex, skipCriteria);

			var splitData = {
				enableHighlight: false,
				enableStoreArea: true,
				offset: offsetValue,
				mode: this.splittingMehods[Data.GetValue(FieldsNames.SplitOption)],
				numberOfPages: Data.GetValue(FieldsNames.SplitNumberOfPage),
				searchString: Data.GetValue(FieldsNames.SplitString),
				searchStringOnFirstPage: Data.GetValue(FieldsNames.SplitSearchOnFirstPage) === "0",
				area: Data.GetValue(FieldsNames.SplitArea),
				caseSensitive: Data.GetValue(FieldsNames.SplitCaseSensitive),
				useRegex: Data.GetValue(FieldsNames.SplitUseRegex)
			};

			splitResult = Lib.DD.Splitting.Split(splitData);
			stringPreviewDocSplitting = JSON.stringify(splitResult);
			Variable.SetValueAsString("previewDocumentNumber", 0);
		}

		Variable.SetValueAsString("previewDocumentSplitted", stringPreviewDocSplitting);
		Variable.SetValueAsString("errorDocumentSplitted", Lib.DD.Splitting.error);
		Variable.SetValueAsString("areasSplitted", JSON.stringify(Lib.DD.Splitting.splitAreas));

		return splitResult;
	}
};

var SaveSettingsHandler = {
	_settingsTable: "DD - Application Settings__",
	_globalSettingsTable: "DD - Application Global Settings__",
	_ignoreSaveFields: {
	},

	Process: function ()
	{
		Sys.DD.NeedConfiguration = false;

		if (!IsOutboundConfiguration())
		{
			Data.SetValue("ConfigurationSelection_Enable__", "1");
			Data.SetValue("MatchDocumentLayout__", "1");
			Data.SetValue("MatchStringWithinDocument__", "0");
		}

		if (this.CheckConfiguration())
		{
			this.CreateVectorStoreCollection();
			this.Save();
		}
	},

	CreateVectorStoreCollection: function ()
	{
		const activateVectorStore = Data.GetValue("Activate_vector_store__");
		const dataToStore = Data.GetValue("Data_To_Store__");
		Log.Verbose("[CreateVectorStoreCollection] Send document to vector store: " + activateVectorStore ? "Yes" : "No");

		if (activateVectorStore)
		{
			const vectorStoreCollection = Data.GetValue("Vector_Store_Collection_ComboBox__");
			Log.Verbose("[CreateVectorStoreCollection] Vector store collection: " + vectorStoreCollection);
			if (vectorStoreCollection)
			{
				// Create collection if not exists, or update description if different
				const collectionsManager = new Sys.ML.VectorStore.Collections.CollectionsManager();
				collectionsManager.getCollection(vectorStoreCollection).then(collection =>
				{
					if (!collection)
					{
						if (dataToStore === "Conversations")
						{
							collectionsManager.createCollection(
								vectorStoreCollection,
								Data.GetValue("DocumentTypeDescription__"),
								["DD - Knowledge Base__"],
								Sys.Helpers.LdapUtil.FilterEqual("Collection_Name__", vectorStoreCollection).toString()
							).then(() =>
							{
								Log.Verbose("[CreateVectorStoreCollection] Collection '" + vectorStoreCollection + "' created with description '" + Data.GetValue("DocumentTypeDescription__") + "'");
							});
						}
						else
						{
							collectionsManager.createCollection(vectorStoreCollection, Data.GetValue("DocumentTypeDescription__")).then(() =>
							{
								Log.Verbose("[CreateVectorStoreCollection] Collection '" + vectorStoreCollection + "' created with description '" + Data.GetValue("DocumentTypeDescription__") + "'");
							});
						}
					}
					else
					{
						Log.Verbose("[CreateVectorStoreCollection] Collection '" + vectorStoreCollection + "' already exists");
					}
				}).catch(err => this.SetError("Error while handling vector store collection: " + err));
			}
		}
	},

	SetError: function (step, message)
	{
		if (step)
		{
			Variable.SetValueAsString("currentStep", step);
		}

		Variable.SetValueAsString("ErrorMessage", message);
		Process.PreventApproval();
	},

	GetFilter: function (configName, documentFamily)
	{
		var familyPart = "";
		if (documentFamily !== "" && documentFamily != null)
		{
			familyPart = "(Family__=" + documentFamily + ")";
		}
		else
		{
			familyPart = "(|(Family__=)(!(Family__=*)))";
		}
		var filter = "(&(ConfigurationName__=" + configName + ")" + familyPart + ")";
		Log.Info("SaveSettingsHandler, filter: " + filter);

		return filter;
	},

	CheckConfigurationUnicity: function ()
	{
		var currentConfigurationName = Data.GetValue("ConfigurationName__");

		if (!currentConfigurationName)
		{
			this.SetError(StepIndexes.General, "Expecting a configuration name");
			return false;
		}

		// ExistingConfigurations only set if no ConfigurationName__ found during customscript
		var existingConfigurations = Variable.GetValueAsString("ExistingConfigurations");
		if (existingConfigurations)
		{
			try
			{
				existingConfigurations = JSON.parse(existingConfigurations);
				for (var i = 0; i < existingConfigurations.length; i++)
				{
					if (existingConfigurations[i].name === currentConfigurationName)
					{
						this.SetError(StepIndexes.General, "_Existing configuration");
						return false;
					}
				}
			}
			catch (e)
			{
				Log.Warn("Exception during check of duplicate configuration name : " + e);
			}
		}
		else
		{
			Log.Info("There is no existing configuration name.");
		}

		return true;
	},

	CheckDuplicateDocumentTypeForAL: function ()
	{
		var isConfigurationAL = Data.GetValue("ConfigurationSelection_Enable__") && Data.GetValue("MatchDocumentLayout__");
		var existingDocumentTypeForAL = Variable.GetValueAsString("ExistingDocumentTypeForAL");
		if (isConfigurationAL && existingDocumentTypeForAL)
		{
			try
			{
				existingDocumentTypeForAL = JSON.parse(existingDocumentTypeForAL);

				var currentDocumentType = Data.GetValue("Document_Type__");
				var loadedDocumentType = Variable.GetValueAsString("DocumentTypeLoaded");
				if (loadedDocumentType !== currentDocumentType && Sys.Helpers.Array.IndexOf(existingDocumentTypeForAL, currentDocumentType) !== -1)
				{
					Variable.SetValueAsString("DocumentTypeNotUnique", "1");
					this.SetError(null, "_Existing document type, must be unique");
					return true;
				}
			}
			catch (e)
			{
				Log.Warn("Exception during check of duplicate document type : " + e);
			}
		}
		else
		{
			Log.Info("There is no existing document type.");
		}
		return false;
	},

	CheckConfiguration: function ()
	{
		if (!this.CheckConfigurationUnicity())
		{
			return false;
		}

		if (Data.GetValue("ConfigurationSelection_Enable__") && Data.GetValue("MatchStringWithinDocument__"))
		{
			if (Sys.Outbound.IsExtractableDocType(Data.GetValue("SubmittedDocType__")))
			{
				if (!regExpAreaValidation.test(Data.GetValue("ConfigurationSelection_Area__")))
				{
					Data.SetError("ConfigurationSelection_Area__", Language.Translate("Expecting a correctly formatted area"));
					return false;
				}
			}
			else if (!Data.GetValue("ConfigurationSelection_Path__"))
			{
				Data.SetError("ConfigurationSelection_Path__", Language.Translate("_Expecting a correctly formatted xpath expression"));
				return false;
			}

			if (!Data.GetValue("ConfigurationSelection_Criteria__"))
			{
				Data.SetError("ConfigurationSelection_Criteria__", Language.Translate("Expecting a non empty criteria"));
				return false;
			}
		}
		else if (Data.GetValue("ConfigurationSelection_Enable__") && Data.GetValue("MatchFilenameRegex__") && !Data.GetValue("Filename_regular_expression__"))
		{
			Data.SetError("Filename_regular_expression__", Language.Translate("Expecting a non empty criteria"));
			return false;
		}

		if (Data.GetValue("Skip_Method__") === "SKIP_AREA")
		{
			if (Sys.Outbound.IsExtractableDocType(Data.GetValue("SubmittedDocType__")))
			{
				if (!regExpAreaValidation.test(Data.GetValue("Skip_Area__")))
				{
					Data.SetError("Skip_Area__", Language.Translate("Expecting a correctly formatted area"));
					return false;
				}
			}

			if (!Data.GetValue("Skip_Criteria__"))
			{
				Data.SetError("Skip_Criteria__", Language.Translate("Expecting a non empty criteria"));
				return false;
			}
		}

		if (this.CheckDuplicateDocumentTypeForAL())
		{
			return false;
		}

		return true;
	},

	Save: function ()
	{
		Log.Info("Saving configuration global settings");
		Sys.DD.NeedConfiguration = false;

		var recordGlobalSettings = Sys.Helpers.Database.CD2CT(this._globalSettingsTable);
		if (recordGlobalSettings.GetLastError() !== 0)
		{
			this.SetError(null, "Could not save global settings : " + recordGlobalSettings.GetLastErrorMessage());
		}

		Log.Info("Saving configuration settings");
		var options =
		{
			fieldsToIgnore: SaveSettingsHandler._ignoreSaveFields,
			specialFields: {}
		};

		options.specialFields[FieldsNames.PDFCommand] =
		{
			GetValue: function (value)
			{
				return value.replace(/\n/g, "\\r\\n");
			}
		};

		var record = Sys.Helpers.Database.CD2CT(this._settingsTable, this.GetFilter(Data.GetValue("ConfigurationName__"), Data.GetValue("Family__")), options);
		if (record.GetLastError() !== 0)
		{
			this.SetError(null, "Could not save settings : " + record.GetLastErrorMessage());
		}

		// Create transport to save reference file
		var recordVars = record.GetVars();
		this.SaveReferenceFile(recordVars.GetValue_String("longid", 0));

		UpdateConfigurationFilenameMask();

		this.PersistCustomFields();

		Log.Info("The configuration has been successfully saved");
	},

	SaveReferenceFile: function (settingsMsn)
	{
		if (settingsMsn && Attach.GetNbAttach() > 0)
		{
			var src = Attach.GetAttach(0).GetAttachFile();
			var ext = Attach.GetExtension(0);

			var cmd = Process.CreateTransport("Copy", true);
			var vars = cmd.GetUninheritedVars();

			var cmdAttach = cmd.AddAttach();
			cmdAttach.SetAttachFile(src);
			var attachVars = cmdAttach.GetVars();
			attachVars.AddValue_String("AttachOutputName", settingsMsn + ext, true);

			vars.AddValue_String("CopyPath", "Resource_ProcessReference", true);
			vars.AddValue_String("OverWriteIfExist", "1", true);
			vars.AddValue_String("Priority", "1", true);

			cmd.Process();
		}
	},

	PersistCustomFields: function ()
	{
		if (!Variable.GetValueAsString("AdditionalFieldsChangeDetection"))
		{
			return false;
		}

		try
		{
			var customFieldsList = JSON.parse(Variable.GetValueAsString("CustomFieldsList__"));
			var errorOutput = Sys.ProcessUpdater.ProcessFields("DD - SenderForm", customFieldsList);

			if (errorOutput)
			{
				throw new Error(errorOutput);
			}

			var commonFieldsList = this.GetCommonCustomFields(customFieldsList);
			this.SpreadCustomCommonFieldsChanges(commonFieldsList);

			this.CleanCurrentCustomFieldsOnSuccess(customFieldsList);
		}
		catch (err)
		{
			this.SetError(null, "Could not save Custom Fields: " + err.message);
			return false;
		}
		return true;
	},

	GetCommonCustomFields: function (customFieldsList)
	{
		return customFieldsList.filter(function (item)
		{
			var activationData = item.field.activationData;
			return activationData && activationData.activationCondition && activationData.activationCondition.field === "Family__";
		});
	},

	SpreadCustomCommonFieldsChanges: function (commonFieldsList)
	{
		if (commonFieldsList.length === 0)
		{
			return false;
		}

		var configsTransport = this.GetActiveInboundConfigTransport();

		if (!configsTransport)
		{
			return false;
		}

		while (configsTransport)
		{
			var vars = configsTransport.GetUninheritedVars();
			var ruid = vars.GetValue("RuidEx", 0);
			var fieldsOrder = this.GetJsonCollectionFromSerializedValue(vars.GetValue_String("FieldsOrder__", 0));

			if (fieldsOrder.length === 0)
			{
				configsTransport = Query.MoveNext();
				continue;
			}

			var fieldsToUpdate = [];

			var item;
			for (var i = 0; i < commonFieldsList.length; i++)
			{
				item = commonFieldsList[i];

				if (item.field.deleted)
				{
					fieldsOrder = this.RemoveDeletedFieldFromCollection(fieldsOrder, item.field.name, "FieldsOrder__");
					if (fieldsOrder)
					{
						fieldsToUpdate.push({ name: "FieldsOrder__", value: fieldsOrder });
					}
				}
			}

			if (fieldsToUpdate.length > 0)
			{
				this.UpdateTransverseConfigFieldsCollections(fieldsToUpdate, ruid);
			}
			configsTransport = Query.MoveNext();
		}

		return true;
	},

	GetJsonCollectionFromSerializedValue: function (fieldValue)
	{
		var collection = [];
		try
		{
			collection = JSON.parse(fieldValue);
		}
		catch (err)
		{
			collection = [];
		}

		return collection;
	},

	RemoveDeletedFieldFromCollection: function (collection, targetName, targetFieldToUpdate)
	{
		var toBeDeleted = false;
		for (var i = 0; i < collection.length; i++)
		{
			toBeDeleted = targetFieldToUpdate === "FieldsOrder__" && collection[i] === targetName;
			if (toBeDeleted)
			{
				collection.splice(i, 1);
				return collection;
			}
		}
		return null;
	},

	UpdateTransverseConfigFieldsCollections: function (fieldsList, ruid)
	{
		var updatableConfig = Process.GetUpdatableTransport(ruid);
		var updatableConfigVars = updatableConfig.GetUninheritedVars();

		for (var i = 0; i < fieldsList.length; i++)
		{
			updatableConfigVars.AddValue_String(fieldsList[i].name, JSON.stringify(fieldsList[i].value), true);
		}

		updatableConfig.Process();
	},

	CleanCurrentCustomFieldsOnSuccess: function (customFieldsList)
	{
		// waiting for fields to be removed through ProcessFields before deleting them from the Wizard collection
		var fieldsOrder = this.GetJsonCollectionFromSerializedValue(Data.GetValue("FieldsOrder__"));
		var flagUpdate = false;
		for (var i = customFieldsList.length - 1; i >= 0; i--)
		{
			var item = customFieldsList[i];

			if (item.field && item.field.deleted)
			{
				customFieldsList.splice(i, 1);
				flagUpdate = true;
				var indexFieldToDelete = fieldsOrder.indexOf(item.field.name);
				if (indexFieldToDelete !== -1)
				{
					fieldsOrder.splice(indexFieldToDelete, 1);
				}
			}
		}

		if (flagUpdate)
		{
			Variable.SetValueAsString("CustomFieldsList__", JSON.stringify(customFieldsList));
			Data.SetValue("FieldsOrder__", JSON.stringify(fieldsOrder));
		}
	},

	GetActiveInboundConfigTransport: function ()
	{
		Query.Reset();
		Query.SetSpecificTable("CDNAME#" + this._settingsTable);
		Query.SetAttributesList("Document_Type__,Family__,FieldsOrder__,RuidEx");
		// get all inbound active configurations except current one
		var ldap = Sys.Helpers.LdapUtil;
		var filter = ldap.FilterAnd(
			ldap.FilterEqual("Routing__", "Routing Message"),
			ldap.FilterNot(
				ldap.FilterEqual("ConfigurationName__", Data.GetValue("ConfigurationName__"))
			),
			ldap.FilterNot(
				ldap.FilterEqual("Configuration_template__", 1)
			),
			ldap.FilterNot(
				ldap.FilterEqual("Enable_Configuration__", 0)
			),
			ldap.FilterEqual("Family__", Data.GetValue("Family__") || "")
		).toString();
		Query.SetFilter(filter);

		if (!Query.MoveFirst())
		{
			return null;
		}

		return Query.MoveNext();
	}
};

function PreventActionIfNeeded(actions, actionName)
{
	var find = false;
	for (var i = 0; i < actions.length && !find; i++)
	{
		find = actions[i].actionName === actionName;
		if (find)
		{
			actions[i].handler.Process();
			if (actions[i].needPreventApproval)
			{
				Process.PreventApproval();
			}
		}
	}
}

function GetProcessById(id)
{
	var query = Process.CreateQuery();
	query.SetSpecificTable("EDD_PROCESS");
	query.SetFilter("ID=" + Process.GetProcessID(id));
	if (!query.MoveFirst())
	{
		this.SetError(null, "Failed to open EDD_PROCESS");
		return null;
	}
	var record = query.MoveNextRecord();
	if (!record)
	{
		this.SetError(null, "Failed to find '" + id + "' in EDD_PROCESS");
		return null;
	}
	return record;
}

function GetNoExtractionJson(processName, configurationName)
{
	Log.Info("Update " + configurationName + " configuration on " + processName);
	var noExtractionJson = {};
	var useFileNameRegex = Data.GetValue("ConfigurationSelection_Enable__") && Data.GetValue("MatchFilenameRegex__");
	if (useFileNameRegex)
	{
		var regexValue = Data.GetValue("Filename_regular_expression__");
		var caseSensitive = Data.GetValue("FileNameRegEx_CaseSensitive__");
		Log.Info("with regex " + regexValue);

		noExtractionJson = { "regex": regexValue, "caseSensitive": caseSensitive };
	}

	return noExtractionJson;
}

function UpdateConfigurationFilenameMask()
{
	var processName = "DD - SenderForm";

	var record = GetProcessById(processName);
	if (!record)
	{
		return;
	}

	var ocrNodeName = "ocr";
	var vars = record.GetVars();
	var ocrNode = vars.FindSubNode(ocrNodeName);
	if (!ocrNode)
	{
		this.SetError(null, "Node <" + ocrNodeName + "> not found in DD Sender form process template");
		return;
	}

	var noExtractionNodeName = "noExtraction";
	var noExtractionJson = JSON.parse(ocrNode.GetValue(noExtractionNodeName, 0));
	var configurationName = Data.GetValue("ConfigurationName__");
	var disableExtraction = Data.GetValue("DisableExtraction__");
	var configurationEnabled = Data.GetValue("Enable_Configuration__");

	var changed = false;
	if (disableExtraction && configurationEnabled)
	{
		noExtractionJson[configurationName] = GetNoExtractionJson(processName, configurationName);
		changed = true;
	}
	else if (noExtractionJson[configurationName])
	{
		Log.Info("Remove " + configurationName + " configuration on " + processName + " to enable extraction");
		delete noExtractionJson[configurationName];
		changed = true;
	}

	if (changed)
	{
		ocrNode.AddValue(noExtractionNodeName, JSON.stringify(noExtractionJson), 1);

		var resultCommit = record.Commit();
		if (resultCommit !== 0)
		{
			var lastErrorMessage = record.GetLastErrorMessage();
			SaveSettingsHandler.SetError(null, "Error " + resultCommit + " during save of sender form process : " + lastErrorMessage);
		}
	}
}


function Run(actions, isForResumbit)
{
	Data.SetValue("DoNotDisplayInDM", "1");
	if ((!isForResumbit && Data.GetActionType() === "approve")
		|| (isForResumbit && Data.GetActionType() === "reprocess"))
	{
		var actionName = Data.GetActionName();
		PreventActionIfNeeded(actions, actionName);
	}
}

function ExtractXML(xmlFile)
{
	Lib.DD.XMLExtraction.SetXMLFileToProcess(xmlFile);

	var extractionType = Sys.Helpers.TryCallFunction("Lib.DD.Customization.Extraction.GetExtractionType") || Data.GetValue("SubmittedDocType__") || "pdf";
	Log.Info("Extraction made using extraction type : '" + extractionType + "'");
	Sys.DD.Extraction.TryExtractDataFromDocument(extractionType);
	// The method below contains the extraction logic defined by the PS.
	Sys.Helpers.TryCallFunction("Lib.DD.Customization.Extraction.ExtractDataFromDocument", extractionType);
}

function IsOutboundConfiguration()
{
	var routing = Data.GetValue("Routing__");
	return routing !== "Routing message";
}

function InitValidation()
{
	if (IsOutboundConfiguration())
	{
		Run([
			{
				actionName: "Splitting",
				needPreventApproval: true,
				handler: SplittingHandler
			},
			{
				actionName: "Splitting_NextPage",
				needPreventApproval: true,
				handler: {
					Process: function ()
					{
						if (SplittingHandler.Process())
						{
							var xmlFile = Attach.GetConvertedFile(Variable.GetValueAsString("XmlIndex"));
							if (xmlFile)
							{
								ExtractXML(xmlFile);
							}
							var currentStep = parseInt(Variable.GetValueAsString("currentStep"), 10);
							Variable.SetValueAsString("currentStep", currentStep + 1);
						}
					}
				}
			},
			{
				actionName: "Splitting_NextPage_XML",
				needPreventApproval: true,
				handler: {
					Process: function ()
					{
						var xmlFile = Attach.GetConvertedFile(Variable.GetValueAsString("XmlIndex"));
						if (xmlFile)
						{
							ExtractXML(xmlFile);
						}
						var currentStep = parseInt(Variable.GetValueAsString("currentStep"), 10);
						Variable.SetValueAsString("currentStep", currentStep + 1);
					}
				}
			},
			{
				actionName: "Save",
				needPreventApproval: false,
				handler: SaveSettingsHandler
			}
		]);
	}
	else
	{
		Run([
			{
				actionName: "Save",
				needPreventApproval: false,
				handler: SaveSettingsHandler
			}
		]);
	}


	Run([{
		actionName: "Document",
		needPreventApproval: true,
		handler: {
			Process: function ()
			{
				var currentStep = parseInt(Variable.GetValueAsString("currentStep"), 10);
				Variable.SetValueAsString("currentStep", currentStep + 1);
			}
		}
	}], true);
}

InitValidation();

gdr.ExtractionScript:
//Force wizard to display splitting step each time a new document is loaded
function GoToSplittingStep()
{
	var currentStep = Variable.GetValueAsString("currentStep");
	var SplittingStep = 1;
	if (currentStep && currentStep !== "0")
	{
		var nbAttach = Attach.GetNbAttach();
		for (var index = 0; index < nbAttach; index++)
		{
			if (Attach.IsProcessedDocument(index))
			{
				Variable.SetValueAsString("currentStep", SplittingStep);
				return true;
			}
		}
	}
	return false;
}

function ExtractZip()
{
	var compressedFile = Attach.GetCompressedFile(0);

	if (!compressedFile)
	{
		return false;
	}

	var entries = compressedFile.GetEntries();
	var pdfIndex = -1;
	var xmlIndex = -1;
	for (var i = 0; i < entries.length; i++)
	{
		var entry = entries[i];
		var extension = (entry.GetExtension() || "").toLowerCase();
		var index = Attach.GetNbAttach();
		var fileName = entry.GetFileName();
		var isAttached;
		if (extension === ".pdf" && pdfIndex === -1)
		{
			pdfIndex = index;
			isAttached = Attach.AttachTemporaryFile(entry.GetFile(), { name: fileName, attachAsConverted: true });
			if (!isAttached)
			{
				throw Language.Translate("_Failed to attach the extracted file");
			}
			Data.SetValue("AttachmentPreviewIndex", pdfIndex);
		}
		else if (extension === ".xml" && xmlIndex === -1)
		{
			xmlIndex = index;
			isAttached = Attach.AttachTemporaryFile(entry.GetFile(), { name: fileName, attachAsConverted: true });
			if (!isAttached)
			{
				throw Language.Translate("_Failed to attach the extracted file");
			}
		}
	}
	if (xmlIndex !== -1)
	{
		Variable.SetValueAsString("XmlIndex", xmlIndex);
	}

	return true;
}

function Main()
{
	Variable.SetValueAsString("XmlIndex", "");
	Data.SetValue("AttachmentPreviewIndex", 0);

	if (Attach.GetNbAttach() === 1)
	{
		var attachExtension = (Attach.GetExtension(0) || "").toLowerCase();
		Variable.SetValueAsString("AttachExtension", attachExtension);
		if (attachExtension === ".zip")
		{
			ExtractZip();
		}
		else if (attachExtension === ".xml")
		{
			Variable.SetValueAsString("XmlIndex", 0);
		}
	}

	GoToSplittingStep();
}

Main();

gdr.PreExtractionScript:
if (!Variable.GetValueAsString("tableParameters"))
{
	var setEmptyParameters = true;
	Log.Info("AncestorsRuid: " + Variable.GetValueAsString("AncestorsRuid"));

	Query.SetSpecificTable("CDNAME#DD - Application Settings__");
	Query.SetFilter("Ruid=" + Variable.GetValueAsString("AncestorsRuid"));
	Query.SetAttributesList("OCRJsonOverrideSettings__");
	if (Query.MoveFirst())
	{
		var trpt = Query.MoveNext();
		if (Query.GetLastError() != 0)
		{
			Log.Info("Error on query table: " + Query.GetLastErrorMessage());
		}
		else if (trpt)
		{
			var processVars = trpt.GetUninheritedVars();
			var ocrOptions = processVars.GetValue_String("OCRJsonOverrideSettings__", 0);
			Log.Info("ocrOptions: " + ocrOptions);
			if (ocrOptions)
			{
				Variable.SetValueAsString("tableParameters", "{ \"ocrjsonoverridesettings\":" + JSON.stringify(ocrOptions) + "}");
				setEmptyParameters = false;
			}
		}
	}
	if (setEmptyParameters)
	{
		Variable.SetValueAsString("tableParameters", "");
	}
}

ui.CustomScript:
/// ==================================
/// Namspace to handle binding between a table listing documents and the preview pannel
/// ==================================
var Tools = {
	GetAreaFromText: function (value)
	{
		if (value)
		{
			var coords = value.split(',');
			if (coords.length !== 4)
			{
				return null;
			}

			for (var i = 0; i < 4; i++)
			{
				if (isNaN(coords[i]))
				{
					return null;
				}
			}

			return {
				left: parseInt(coords[0], 10),
				top: parseInt(coords[1], 10),
				width: parseInt(coords[2], 10),
				height: parseInt(coords[3], 10)
			};
		}
		return null;
	},
	IsExtractable: function ()
	{
		var extrableDocType = ["pdf", "tif"];
		var docType = Controls.SubmittedDocType__.GetValue();
		return extrableDocType.indexOf(docType) >= 0;
	},
	IsExtractionDisabled: function ()
	{
		return Controls.DisableExtraction__.IsChecked();
	},
	HasTemplateId: function ()
	{
		var templateIDJSON = Controls.TemplateIdList__.GetValue();
		if (templateIDJSON)
		{
			try
			{
				var templateIdList = JSON.parse(templateIDJSON);
				return templateIdList && templateIdList.length > 0;
			}
			catch (exception)
			{
				Log.Error("Error while parsing JSON templateIDList: " + exception);
			}
		}
		return false;
	},
	translations: {
		previewSplittedDoc: Language.Translate("_PreviewSplittedDoc"),
		formattedAreaExpected: Language.Translate("Expecting a correctly formatted area"),
		formattedXPathExpected: Language.Translate("_Expecting a correctly formatted xpath expression"),
		nonEmptyCriteriaExpected: Language.Translate("Expecting a non empty criteria"),
		configurationNameExpected: Language.Translate("Expecting a configuration name"),
		configurationExisting: Language.Translate("_Existing configuration"),
		filenameRegexExisting: Language.Translate("_Existing file name regex"),
		documentTypeExisting: Language.Translate("_Existing document type, must be unique"),
		moreOptions: Language.Translate("More options"),
		noValidFileType: Language.Translate("Please select the format that matches the uploaded files")
	}
};

/// ==================================
/// Namspace to handle the "Extraction" step
/// ==================================
var ExtractionUI = {
	previewMaxDocuments: 100,
	outboundExtractionPanels: [Controls.Recipient_pane, Controls.Sender_pane, Controls.Billing_info_extraction_pane, Controls.extraction_feature_pane, Controls.Additional_fields_control_pane, Controls.Document_data_pane, Controls.Advanced_extraction_pane],
	inboundExtractionPanels: [Controls.Additional_fields_control_pane, Controls.Document_data_pane, Controls.extraction_feature_pane, Controls.Advanced_extraction_pane],
	controlsNotToRefresh: ["FieldsOrder__", "Document_Type_SDAForm__", "Show_recipient_id__", "Show_comment__", "Show_document_number__", "Show_document_priority__"],
	_refreshControls: function (params)
	{
		var isDisableExtraction = Tools.IsExtractionDisabled();
		if (isDisableExtraction)
		{
			return;
		}
		var doc = Attach.GetProcessedDocument();
		if (doc)
		{
			doc.UpdateInfoPageCache(params.infoPageRange.startPage, params.infoPageRange.endPage, function ()
			{
				var panelCollection = ExtractionUI.GetExtractionPanels();
				for (var i in panelCollection)
				{
					var controls = GetPanelControlsToRefresh(panelCollection[i]);
					for (var j in controls)
					{
						if (typeof controls[j].GetValueFromExtraction === "function")
						{
							controls[j].SetValue(controls[j].GetValueFromExtraction(params.docRange.startPage, params.docRange.endPage));
						}
					}
				}
			});
		}
	},

	GetExtractionPanels: function ()
	{
		if (IsOutboundConfiguration())
		{
			return this.outboundExtractionPanels;
		}

		return this.inboundExtractionPanels;
	},

	HandleConfigurationName: function ()
	{
		Data.SetExtractionConfiguration(Data.GetValue("ConfigurationName__"));
	},

	Init: function ()
	{
		this.HandleConfigurationName();
		var splitRanges = PreviewHelper.GetSplitRanges();
		if (splitRanges && splitRanges.length > 0)
		{
			var _infoPageRange = this.GetExtractionPageRange(splitRanges);
			this._refreshControls({ docRange: splitRanges[PreviewHelper.GetSelectedDoc()], infoPageRange: _infoPageRange });
		}
	},
	GetExtractionPageRange: function (splitRanges)
	{
		var lastDocIndex = Math.min(ExtractionUI.previewMaxDocuments, splitRanges.length) - 1;
		return {
			startPage: splitRanges[0].startPage,
			endPage: splitRanges[lastDocIndex].endPage
		};
	},
	SetReadOnly: function (readOnly)
	{
		var panelCollection = ExtractionUI.GetExtractionPanels();
		for (var i in ExtractionUI.GetExtractionPanels())
		{
			var controls = GetPanelControlsToRefresh(panelCollection[i]);
			for (var j in controls)
			{
				controls[j].SetReadOnly(readOnly);
			}
		}
	},
	CleanExtractionFields: function ()
	{
		var isDisableExtraction = Tools.IsExtractionDisabled();
		if (!isDisableExtraction)
		{
			return;
		}
		var panelCollection = ExtractionUI.GetExtractionPanels();
		for (var i in panelCollection)
		{
			var controls = GetPanelControlsToRefresh(panelCollection[i]);
			for (var j in controls)
			{
				controls[j].SetValue("");
			}
		}
	}
};

function GetPanelControlsToRefresh(ctrlPanel)
{
	var controls = ctrlPanel.GetControls();
	var controlsToIgnore = ExtractionUI.controlsNotToRefresh;
	for (var i = controls.length - 1; i >= 0; i--)
	{
		if (controlsToIgnore.indexOf(controls[i].GetName()) !== -1)
		{
			controls.splice(i, 1);
		}
	}
	return controls;
}

var PreviewHelper = {
	_selectedDoc: null,
	// The table listing documents that can be viewed in preview (if any)
	_boundPreviewTable: null,
	// The column (if any) that can be used to show the selected line in the table, using an arrow image
	_arrowColumnName: "",

	Init: function (table, arrowColName)
	{
		this._boundPreviewTable = table;
		this._arrowColumnName = arrowColName;
		this._boundPreviewTable.OnClick = function (row)
		{
			PreviewHelper.SetSelectedDoc(row.GetLineNumber(true) - 1);
		};
		this._boundPreviewTable.OnRefreshRow = function ()
		{
			PreviewHelper.HighlightRow(PreviewHelper.GetSelectedDoc());
		};
	},

	GetSelectedDoc: function ()
	{
		if (!this._selectedDoc)
		{
			this._selectedDoc = parseInt(Variable.GetValueAsString("previewDocumentNumber"), 10) || 0;
		}

		return this._selectedDoc;
	},

	GetSplitRanges: function ()
	{
		if (!this._splitRanges)
		{
			this._splitRanges = JSON.parse(Variable.GetValueAsString("previewDocumentSplitted"));
		}

		return this._splitRanges;
	},

	SetControlsValueFromExtraction: function (splitRange)
	{
		if (splitRange)
		{
			ExtractionUI._refreshControls({ docRange: splitRange, infoPageRange: splitRange });
		}
	},

	SetSelectedDoc: function (docNumber)
	{
		//Set the Preview document
		PreviewHelper._selectedDoc = docNumber;
		Variable.SetValueAsString("previewDocumentNumber", PreviewHelper._selectedDoc);
		var range = PreviewHelper.GetSplitRanges()[PreviewHelper._selectedDoc];
		Controls.PreviewPanel.SetPagesToDisplay(range.startPage, range.endPage);
		PreviewHelper.SetControlsValueFromExtraction(range);

		//Update the table that is bound
		if (PreviewHelper._boundPreviewTable)
		{
			PreviewHelper._boundPreviewTable.DisplayItem(docNumber);
			PreviewHelper.HighlightRow(docNumber);
		}
	},

	HighlightRow: function (docNumber)
	{
		for (var i = 0; i < PreviewHelper._boundPreviewTable.GetLineCount(); i++)
		{
			var currentRow = PreviewHelper._boundPreviewTable.GetRow(i);
			var currentRowDocNum = currentRow.GetLineNumber(true) - 1;
			if (currentRowDocNum === docNumber)
			{
				currentRow.AddStyle("highlight");
				if (PreviewHelper._arrowColumnName)
				{
					currentRow[PreviewHelper._arrowColumnName].SetImageURL("public\\arrow.png", true);
				}
			}
			else
			{
				currentRow.RemoveStyle("highlight");
				if (PreviewHelper._arrowColumnName)
				{
					currentRow[PreviewHelper._arrowColumnName].SetImageURL();
				}
			}
		}
	}
};

/// ==================================
/// Namspace to handle the "Splitting" step
/// ==================================
var SplitUI = {
	_splitRanges: null,
	hasChanged: true,

	isOnSelectPageEnabled: false,

	GetRangeNbPage: function (splitRange)
	{
		return splitRange.endPage - splitRange.startPage + 1;
	},

	GetSplittingDetails: function (splitRanges)
	{
		splitRanges = splitRanges || PreviewHelper.GetSplitRanges();
		var details = {
			"nbPages": 0,
			"nbDocuments": splitRanges.length
		};
		for (var index = 0; index < splitRanges.length; index++)
		{
			details.nbPages += this.GetRangeNbPage(splitRanges[index]);
		}

		return details;
	},

	PreviewSplit: function (preViewIfNeeded)
	{
		function FillSplitPreviewTable(splitResult)
		{
			ProcessInstance.SetSilentChange(true);
			var ctrlPreviewTable = Controls.Split_preview_table__;
			ctrlPreviewTable.SetWidth("100%");
			ctrlPreviewTable.SetExtendableColumn("Split_PageRange__");
			ctrlPreviewTable.SetItemCount(0);
			ctrlPreviewTable.SetAtLeastOneLine(false);

			for (var i = 0; i < splitResult.length; i++)
			{
				var item = ctrlPreviewTable.AddItem(false);
				item.SetValue("Split_ViewAction__", Tools.translations.previewSplittedDoc);
				item.SetValue("Split_Pages_Count__", SplitUI.GetRangeNbPage(splitResult[i]));
				item.SetValue("Split_PageRange__", splitResult[i].startPage + "-" + splitResult[i].endPage);
			}
			ProcessInstance.SetSilentChange(false);
		}

		function FillSplitDetails(splitResult)
		{
			var details = SplitUI.GetSplittingDetails(splitResult);
			Controls.Split_Pages_Count__.SetValue(details.nbPages);
			Controls.Split_Documents_Count__.SetValue(details.nbDocuments);
		}

		PreviewHelper.Init(Controls.Split_preview_table__, "Arrow__");

		if (preViewIfNeeded && !SplitUI.hasChanged)
		{
			return;
		}

		var previewRanges = PreviewHelper.GetSplitRanges();
		if (previewRanges && previewRanges.length > 0)
		{
			FillSplitPreviewTable(previewRanges);
			FillSplitDetails(previewRanges);
			// Take only the first splitted document for the preview
			PreviewHelper.SetSelectedDoc(PreviewHelper.GetSelectedDoc());
			SplitUI.hasChanged = false;
		}
		else
		{
			var errorString = Variable.GetValueAsString("errorDocumentSplitted");
			if (errorString !== null)
			{
				Popup.Alert(errorString, true, null, "_Status");
			}
			SplitUI.ResetPreview();
		}
	},

	ResetPreview: function ()
	{
		Controls.PreviewPanel.ResetPagesToDisplay();
		Controls.PreviewPanel.ClearHighlights();

		SplitUI._selectedDoc = null;
		SplitUI._splitRanges = null;
		SplitUI.hasChanged = true;
		Variable.SetValueAsString("previewDocumentSplitted", JSON.stringify([]));
		Variable.SetValueAsString("previewDocumentNumber", 0);
		Variable.SetValueAsString("errorDocumentSplitted", "");
		Controls.Split_Pages_Count__.SetValue("");
		Controls.Split_Documents_Count__.SetValue("");
		Controls.Split_Information_pane.Hide(true);
	},

	DrawSplittingPreview: function ()
	{
		var isOffset = Controls.Skip_Method__.GetValue() === "SKIP_AREA" || Controls.Split_Offset__.GetValue();
		var type = Controls.Split_DivisionMethod__.GetValue();
		var stringAtEnd = type === "ONSTRING" && Controls.Split_Location__.GetValue() === "1";
		Sys.Wizard.Tools.DrawSplittingPreview(isOffset, type, stringAtEnd, Controls.HTMLSplittingPreview__);
		Controls.Spacer_line3__.Hide(false);
		Controls.HTMLSplittingPreview__.Hide(false);
	},

	DrawAreas: function ()
	{
		Controls.PreviewPanel.ClearHighlights();
		SplitUI.DrawSplitArea();
		if (Controls.Split_DivisionMethod__.GetValue() === "ONSTRING")
		{
			SplitUI.DrawStringArea();
		}
	},

	OnPreviewSelectPage: function ()
	{
		if (SplitUI.isOnSelectPageEnabled)
		{
			SplitUI.DrawAreas();
		}
	},

	DrawSplitArea: function ()
	{
		var splitMethod = Controls.Split_DivisionMethod__.GetValue();
		if (splitMethod === "ONSTRING" || splitMethod === "ONAREA")
		{
			var area = Tools.GetAreaFromText(Controls.Split_Area__.GetText());
			if (area)
			{
				var splitRanges = PreviewHelper.GetSplitRanges();
				var startPage = splitRanges && splitRanges.length > 0 ?
					splitRanges[PreviewHelper.GetSelectedDoc()].startPage - 1 :
					0;

				var selectedPage = Controls.PreviewPanel.GetSelectedPage() || startPage + 1;
				area.page = selectedPage - startPage;
				Controls.PreviewPanel.Highlight(area);
			}
		}
	},

	DrawStringArea: function ()
	{
		var selectedRangePage = Variable.GetValueAsString("previewDocumentNumber") || 0;
		var splitRanges = PreviewHelper.GetSplitRanges();
		if (!splitRanges || splitRanges.length <= 0 || selectedRangePage >= splitRanges.length || PreviewHelper.GetSelectedDoc() >= splitRanges.length)
		{
			Log.Warn("GetSplitRanges() returns an invalid value: " + splitRanges);
			return;
		}
		// GetSelectedPage return 0 before document is loaded, load with the first doc
		var selectedPage = Controls.PreviewPanel.GetSelectedPage() || splitRanges[0].startPage;
		var startPage = splitRanges[PreviewHelper.GetSelectedDoc()].startPage;
		var areasSplittedDocument = JSON.parse(Variable.GetValueAsString("areasSplitted"));
		if (areasSplittedDocument)
		{
			for (var i = 0; i < areasSplittedDocument.length; i++)
			{
				// areasSplittedDocument page is 0-based, selectedPage is 1-based
				if (areasSplittedDocument[i].page === selectedPage - 1)
				{
					// page in highlight is 1-based
					Controls.PreviewPanel.Highlight({
						left: areasSplittedDocument[i].x,
						top: areasSplittedDocument[i].y,
						width: areasSplittedDocument[i].width,
						height: areasSplittedDocument[i].height,
						page: selectedPage - startPage + 1
					});
					break;
				}
			}
		}
	},

	HandleSkipVisibility: function ()
	{
		var docType = Controls.SubmittedDocType__.GetValue();
		var isDisableExtraction = Tools.IsExtractionDisabled();
		var isAutolearningConf = Tools.HasTemplateId() || Controls.IsAutolearningConf__.GetValue() === "1";
		var isSplitting = docType === "pdf" && !isDisableExtraction && !isAutolearningConf;

		var skipValue = Controls.Skip_Method__.GetValue();
		var skipOffset = skipValue !== "SKIP_AREA";
		var skipArea = skipValue === "SKIP_AREA";

		Controls.Split_Offset__.Hide(!isSplitting || !skipOffset);
		Controls.Skip_Area__.Hide(!isSplitting || !skipArea);
		Controls.Skip_Criteria__.Hide(!isSplitting || !skipArea);
		Controls.Skip_CriteriaIsRegex__.Hide(!isSplitting || !skipArea);
		Controls.Skip_CriteriaMatchCase__.Hide(!isSplitting || !skipArea);

		Controls.Skip_Area__.SetRequired(isSplitting && skipArea);
		Controls.Skip_Criteria__.SetRequired(isSplitting && skipArea);
	},

	HandleSkipArea: function ()
	{
		if (Tools.GetAreaFromText(this.GetText()))
		{
			return;
		}

		var area = Data.GetArea(this.GetName());
		var value = this.GetValue();
		if (area)
		{
			var areaValue = Controls.Skip_Area__.GetValue();
			if (!areaValue || this.GetName() === Controls.Skip_Area__.GetName())
			{
				Controls.Skip_Area__.SetValue(area.left + ', ' + area.top + ', ' + area.width + ', ' + area.height);
			}

			var criteriaValue = Controls.Skip_Criteria__.GetValue();
			if (!criteriaValue || this.GetName() === Controls.Skip_Criteria__.GetName())
			{
				Controls.Skip_Criteria__.SetValue(value);
			}

			Controls.PreviewPanel.ClearHighlights();
			area.page++;
			Controls.PreviewPanel.Highlight(area);
		}
	},

	SetControlsVisibility: function ()
	{
		var comboValue = Controls.Split_DivisionMethod__.GetValue();

		var numberPageVisible = comboValue === "NPAGES";
		var stringSplitVisible = comboValue === "ONSTRING";
		var useRegex = Controls.Split_UseRegex__.IsChecked();
		var areaVisible = comboValue === "ONAREA";

		Controls.Split_UseRegex__.SetLabel(areaVisible ? "Split_UseAreaFilter__" : "Split_UseRegex__");

		Controls.Split_NumberPages__.Hide(!numberPageVisible);
		Controls.Split_Location__.Hide(!stringSplitVisible);
		Controls.Split_String__.Hide(!stringSplitVisible);
		Controls.Split_UseRegex__.Hide(!(stringSplitVisible || areaVisible));
		Controls.Split_CaseSensitive__.Hide(!(stringSplitVisible || (areaVisible && useRegex)));
		Controls.Split_Area__.Hide(!(stringSplitVisible || areaVisible));
		Controls.Split_AreaRegex__.Hide(!(areaVisible && useRegex));
		Controls.Split_AreaMustBeFilled__.Hide(!areaVisible);
		SplitUI.HandleSkipVisibility();
	},

	HandleDivisionMethod: function ()
	{
		SplitUI.SetControlsVisibility();
		SplitUI.HandlePreviewCtrlChange();
	},

	HandleSkipMethod: function ()
	{
		SplitUI.SetControlsVisibility();
		SplitUI.DrawSplittingPreview();
	},

	HandleAreaChange: function ()
	{
		SplitUI.HandleChange();
		if (Tools.GetAreaFromText(this.GetText()))
		{
			return;
		}

		var area = Data.GetArea(this.GetName());
		Controls.Split_Area__.ResetUserArea();
		if (area)
		{
			this.SetValue(area.left + ', ' + area.top + ', ' + area.width + ', ' + area.height);
			SplitUI.DrawAreas();
		}
	},

	HandlePreviewCtrlChange: function ()
	{
		SplitUI.HandleChange();
		SplitUI.DrawSplittingPreview();
	},

	HandleChangeRegex: function ()
	{
		SplitUI.SetControlsVisibility();
		SplitUI.HandleChange();
	},

	HandleChange: function ()
	{
		SplitUI.hasChanged = true;
	},

	MakeSplit: function ()
	{
		var couldSplit = true;
		if (Controls.Skip_Method__.GetValue() === "SKIP_AREA")
		{
			if (Tools.IsExtractable() && !Tools.GetAreaFromText(Controls.Skip_Area__.GetValue()))
			{
				Controls.Skip_Area__.SetError(Tools.translations.formattedAreaExpected);
				couldSplit = false;
			}

			if (!Controls.Skip_Criteria__.GetValue())
			{
				Controls.Skip_Criteria__.SetError(Tools.translations.nonEmptyCriteriaExpected);
				couldSplit = false;
			}
		}

		if (couldSplit && Attach.IsProcessedDocument(0))
		{
			CustomFields.SaveTemporayExtractionData();
			ProcessInstance.Approve("Splitting");
		}
	},

	HideSplittingDatas: function ()
	{
		Controls.Spacer_line3__.Hide(true);
		Controls.Split_Information_pane.Hide(true);
		Controls.HTMLSplittingPreview__.SetHTML("");
	},

	Init: function ()
	{
		// --------------------
		// Here we go !
		// --------------------
		var docType = Controls.SubmittedDocType__.GetValue();
		var isDisableExtraction = Tools.IsExtractionDisabled();
		var isSplitting = docType === "pdf" && !isDisableExtraction;
		if (!isSplitting)
		{
			HandleSubmittedDocType();
			SplitUI.SetControlsVisibility();
			SplitUI.HideSplittingDatas();
		}
		else
		{
			SplitUI.hasChanged = true;

			HandleSubmittedDocType();
			ExtractionUI.HandleConfigurationName();

			SplitUI.SetControlsVisibility();
			SplitUI.DrawSplittingPreview();
			SplitUI.DrawAreas();
			SplitUI.PreviewSplit();

			SplitUI.isOnSelectPageEnabled = true;
		}
		SplitUI.HandleSkipVisibility();
		RefreshHTMLToggles();
	},

	OnQuit: function (goToNext)
	{
		var result = true;
		Controls.Skip_Area__.SetError();
		Controls.Skip_Criteria__.SetError();

		if (Controls.Skip_Method__.GetValue() === "SKIP_AREA")
		{
			if (Tools.IsExtractable() && !Tools.GetAreaFromText(Controls.Skip_Area__.GetValue()))
			{
				Controls.Skip_Area__.SetError(Tools.translations.formattedAreaExpected);
				result = false;
			}

			if (!Controls.Skip_Criteria__.GetValue())
			{
				Controls.Skip_Criteria__.SetError(Tools.translations.nonEmptyCriteriaExpected);
				result = false;
			}
		}

		if (result && goToNext && Attach.IsProcessedDocument(0))
		{
			//First passage with an attachment or if the attachment file changed

			if (SplitUI.hasChanged)
			{
				CustomFields.SaveTemporayExtractionData();
				ProcessInstance.Approve("Splitting_NextPage");
				result = false;
			}
			else if (Variable.GetValueAsString("XmlIndex"))
			{
				CustomFields.SaveTemporayExtractionData();
				ProcessInstance.Approve("Splitting_NextPage_XML");
				result = false;
			}
		}

		var splitMethod = Data.GetValue("Split_DivisionMethod__");
		if ((splitMethod === "ONAREA" || splitMethod === "ONSTRING") && Data.GetValue("Split_UseRegex__") && !CheckRegularExpression("Split_String__"))
		{
			result = false;
		}

		return result;
	}
};

