		var outboundDefaultRoutingMethods = ["MOD=Default_MOD", "PORTAL=Default_PORTAL", "SM=Default_EMAIL", "FGFAXOUT=Default_FAX", "OTHER=Default_OTHER", "NONE=Default_NONE"];
