function CheckRegularExpression(fieldName)
{
	var strRegex = Data.GetValue(fieldName);
	var valid = true;
	try
	{
		var regex = new RegExp(strRegex);
		valid = !!regex;
	}
	catch (e)
	{
		valid = false;
	}
	if (!valid)
	{
		Data.SetError(fieldName, "Invalid regular expression");
		return false;
	}
	return valid;
}

